import axios from 'axios';
import {
  ConversionOtherBankRequestDTO,
  ConversionSameBankRequestDTO,
  DepositRequestDTO,
  exchangeResponseDTO,
  remitCheckResponseDTO,
  FindRecipientRequestDTO,
  FindRecipientResponseDTO,
  PaymentRequestDTO,
  RecentRecipientsRequestDTO,
  RemitRequestDTO,
  ResultSearchDTO,
  ResultSearchResponseDTO,
  TopUpRequestDTO,
  TopUpResponseDTO,
  TxSearchDTO,
  TxSearchResponseDTO,
  exchangeCreateTrnscResponseDTO,
} from '~/entities/exchange/api/dtos/types';
import { WalletHistoryListResponseDTO } from '~/entities/wallet/api/dtos/wallet-history-list';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

export const exchangeApi = {
  // 타행 환전
  conversionOtherBank: ({ insttCd, dsuseAmmount, cstmrNo }: ConversionOtherBankRequestDTO) =>
    resultify(
      axios.post<boolean>(API_URLS.sendDsuseEmoneyInfo, {
        insttCd,
        dsuseAmmount,
        cstmrNo,
      }),
    ),

  // 동일 은행 환전
  conversionSameBank: ({ dsuseAmmount, cstmrNo }: ConversionSameBankRequestDTO) =>
    resultify(
      axios.post<boolean>(API_URLS.dsuseOwnEmoneyToken, {
        dsuseAmmount,
        cstmrNo,
      }),
    ),

  // 수취인 찾기
  findRecipient: ({ aliasNm, trgetInstt, bizNo }: FindRecipientRequestDTO) =>
    resultify(
      axios.post<FindRecipientResponseDTO>(API_URLS.remittanceFindUserAlias, {
        aliasNm,
        trgetInstt,
        bizNo,
      }),
    ),

  // 결제 (변동형QR)
  payment: ({ tbPayMastr }: PaymentRequestDTO) =>
    resultify(
      axios.post<exchangeResponseDTO>(API_URLS.payment, {
        tbPayMastr,
      }),
    ),
  // 결제 (고정형QR)
  mrmPayment: ({ tbPayMastr }: PaymentRequestDTO) =>
    resultify(
      axios.post<exchangeResponseDTO>(API_URLS.mrmPayment, {
        tbPayMastr,
      }),
    ),

  // 현금영수증
  // receipt: (bizNo: string) =>
  //   resultify(
  //     axios.post<string>(API_URLS.receipt(bizNo), {
  //       bizNo,
  //     }),
  //   ),

  // 최근 수취인 목록
  getRecentRecipients: ({ paging, search }: RecentRecipientsRequestDTO) =>
    resultify(
      axios.post<WalletHistoryListResponseDTO>(API_URLS.recentRecipients, {
        paging,
        search,
      }),
    ),

  // DC1 송금 - 거래 생성 (삭제)
  remitDC1: ({ tbAcnutMastr }: RemitRequestDTO) =>
    resultify(
      axios.post<remitCheckResponseDTO>(API_URLS.depositTrans, {
        tbAcnutMastr,
      }),
    ),

  // DC1 송금 - 거래 검토
  remitDC1CheckTrnsc: ({ tbAcnutMastr }: RemitRequestDTO) =>
    resultify(axios.post<remitCheckResponseDTO>(API_URLS.depositCheckTrans(tbAcnutMastr.draftCd!), { tbAcnutMastr })),

  // DC1 송금 - 거래 완료
  remitDC1Execute: ({ tbAcnutMastr }: RemitRequestDTO) =>
    resultify(axios.post<exchangeResponseDTO>(API_URLS.depositTransExecute(tbAcnutMastr.txCd!))),

  // DC2 송금
  remitDC2: ({ tbAcnutMastr }: RemitRequestDTO) =>
    resultify(
      axios.post<boolean>(API_URLS.emoneyTrans, {
        tbAcnutMastr,
      }),
    ),

  // 예금 전환
  convertToDeposit: ({ tbAcnutMastr }: DepositRequestDTO) =>
    resultify(
      axios.post<exchangeResponseDTO>(API_URLS.convertToDeposit, {
        tbAcnutMastr,
      }),
    ),
  // 예금 전환 - 거래 생성
  convertToDepositCreateTrnsc: ({ tbAcnutMastr }: DepositRequestDTO) =>
    resultify(
      axios.post<exchangeCreateTrnscResponseDTO>(API_URLS.convertToDepositCreateTrnsc, {
        tbAcnutMastr,
      }),
    ),

  // 예금 전환 - 거래 완료
  convertToDepositExecuteTrnsc: (txCd: string) =>
    resultify(axios.post<exchangeResponseDTO>(API_URLS.convertToDepositExecuteTrnsc(txCd))),

  // 충전
  topUp: ({ emoneyAmmount, cstmrNo }: TopUpRequestDTO) =>
    resultify(
      axios.post<TopUpResponseDTO>(API_URLS.topUp, {
        emoneyAmmount,
        cstmrNo,
      }),
    ),

  // 전환 입금
  convertToToken: ({ tbAcnutMastr }: DepositRequestDTO) =>
    resultify(
      axios.post<exchangeResponseDTO>(API_URLS.convertToToken, {
        tbAcnutMastr,
      }),
    ),

  //전환입금 - 거래 생성
  convertToTokenCreateTrnsc: ({ tbAcnutMastr }: DepositRequestDTO) =>
    resultify(
      axios.post<exchangeCreateTrnscResponseDTO>(API_URLS.convertToTokenCreateTrnsc, {
        tbAcnutMastr,
      }),
    ),

  //전환입금 - 거래 완료
  convertToTokenExecuteTrnsc: (txCd: string) =>
    resultify(axios.post<exchangeResponseDTO>(API_URLS.convertToTokenExecuteTrnsc(txCd))),

  // tx 조회
  txSearch: ({ tbPayMastr }: TxSearchDTO) =>
    resultify(
      axios.post<TxSearchResponseDTO>(API_URLS.txSearch, {
        tbPayMastr,
      }),
    ),
  // 결과 조회
  resultSearch: ({ tbPayMastr }: ResultSearchDTO) =>
    resultify(
      axios.post<ResultSearchResponseDTO>(API_URLS.resultSearch, {
        tbPayMastr,
      }),
    ),
} as const;
